import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem77 protege identidade operação e idempotência sem inventar limites',()=>{for(const [id,titulo] of [['fQAJIJDeSjtSvdevGCQm','Parafusadeira Furadeira De Impacto A Bateria 21V 3/8” Bivolt 1400 Rpm Com Acessórios E Maleta TB-21PZW The Black Tools'],['g3QWQpsMAD73Kg7gMUzm','Torneira Gourmet Luxo Flexível Cozinha Parede 2 Jatos Pia Metal Cor Aço Inox e Preto- Marca Camperluz'],['GhxvMZYaZM60wLsGuNdw','Esfregão Perfect Pro Mop 360° Balde Inox Cabo Longo Microfibra 16L']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/maior resistência|instalação fácil|economia comprovada/i);assert.doesNotMatch(x.comentario,/\b\d+\s*(?:Nm|N\.m|mca|bar)\b/);}});
